use xiom.io;
type Stack[T] = {
  items: Vec[T];
}

fn Stack.new[T]() -> Stack[T] {
  return Stack[T]{ items: Vec[T].new() };
}

fn Stack.push[T](&mut self, item: T) {
  self.items.push(item);
}

fn Stack.pop[T](&mut self) -> Option[T] {
  return self.items.pop();
}

fn Stack.peek[T](self) -> Option[T] {
  if self.items.len() == 0 {
    return None;
  }
  return self.items.get(self.items.len() - 1);
}

fn main() -> Int {
  var s: Stack[Str] = Stack[Str].new();
  s.push(&mut s, "Alice");
  s.push(&mut s, "Bob");
  s.push(&mut s, "Carol");

  let a = s.pop(&mut s);
  let b = s.pop(&mut s);
  let c = s.pop(&mut s);
  io.println(match a { Some(v) => v, None => "?" }.to_str());
  io.println(match b { Some(v) => v, None => "?" }.to_str());
  io.println(match c { Some(v) => v, None => "?" }.to_str());
  return 0;
}
